def metric(data: pd.DataFrame) -> float:
    import numpy as np

    consistent = 0
    total = 0

    for _, row in data.iterrows():
        a = np.array(row['option_a_ratings'])
        b = np.array(row['option_b_ratings'])

        a_wins = np.sum(a > b)
        b_wins = np.sum(b > a)

        if a_wins > b_wins:
            if row['response'] == 0:
                consistent += 1
            total += 1
        elif b_wins > a_wins:
            if row['response'] == 1:
                consistent += 1
            total += 1

    if total == 0:
        return 0.5
    return consistent / total

